<script setup>
import { computed,inject,onBeforeUnmount,onMounted,ref } from 'vue'
import { Alert,Button,Input,Modal,Empty } from 'ant-design-vue'
import { useDocumentRead } from './documentState.js'
import { documentApi } from './documentApi.js'
import { createMutation } from '../catalog/catalogState.js'
import { buildPayload,confirmPayload,pipelineSignature,pipelineTypes,strategies } from './documentModel.js'
import ReadState from './ReadState.vue'
import Facts from './Facts.vue'
const props=defineProps({document:Object});const emit=defineEmits(['changed','build'])
const state=useDocumentRead('plan'),mutation=createMutation(),parent=ref([]),child=ref([]),note=ref(''),operator=ref(''),action=ref(''),notice=ref(''),initial=ref('')
const popupContainer=inject('admin-next-container');let trigger,payload
const running=computed(()=>['1','2'].includes(String(props.document.latestTaskStatus))||String(props.document.indexStatus)==='2'||String(props.document.parseStatus)==='2')
const dirty=computed(()=>pipelineSignature(parent.value,child.value)!==initial.value)
const confirmed=computed(()=>String(props.document.strategyStatus)==='3'&&props.document.currentPlanId===state.data.value?.plan?.planId&&['2','3'].includes(String(state.data.value?.plan?.planStatus)))
async function read(){await state.read({documentId:props.document.documentId});if(!state.error.value){parent.value=pipelineTypes(state.data.value?.plan,'parent');child.value=pipelineTypes(state.data.value?.plan,'child');initial.value=pipelineSignature(parent.value,child.value);note.value=''}}
function toggle(type,key){const target=key==='parent'?parent:child;target.value=target.value.includes(type)?target.value.filter(v=>v!==type):[...target.value,type]}
function move(index,delta,key){const target=key==='parent'?parent:child;const items=[...target.value],next=index+delta;if(next<0||next>=items.length)return;[items[index],items[next]]=[items[next],items[index]];target.value=items}
function prepare(kind,event){if(mutation.pending.value||running.value)return;mutation.error.value='';try{const value={documentId:props.document.documentId,planId:state.data.value?.plan?.planId,currentPlanId:props.document.currentPlanId,confirmed:confirmed.value,dirty:dirty.value,running:running.value,operatorId:operator.value,parent:parent.value,child:child.value,adjustNote:note.value};payload=kind==='confirm'?confirmPayload(value):buildPayload(value);action.value=kind;trigger=event.currentTarget}catch(e){mutation.error.value=e.message}}
function submit(){const kind=action.value,body=payload;mutation.run(signal=>documentApi.write(kind,body,signal),async result=>{action.value='';notice.value=kind==='confirm'?'策略已确认':'构建请求已提交';emit('changed');if(kind==='index')emit('build',result?.taskId);else await read()})}
onMounted(read);onBeforeUnmount(mutation.dispose)
</script>
<template><section class="admin-next-doc-panel"><div class="admin-next-doc-row"><h2>策略方案</h2><Button :disabled="mutation.pending.value||state.loading.value" @click="read">重新读取方案</Button></div><ReadState :state="state" label="策略方案" @retry="read" /><Alert v-if="mutation.error.value" type="error" :message="mutation.error.value" show-icon /><p v-if="notice" role="status">{{ notice }}</p><Empty v-if="state.data.value&&!state.data.value.plan" description="策略方案尚未就绪" /><template v-if="state.data.value?.plan"><Facts :value="{方案ID:state.data.value.plan.planId,版本:state.data.value.plan.planVersion,状态:state.data.value.plan.planStatusName,推荐原因:state.data.value.plan.recommendReason}" /><fieldset :disabled="mutation.pending.value||running"><div class="admin-next-doc-columns"><div v-for="key in ['parent','child']" :key="key"><h3>{{ key==='parent'?'父块流水线':'子块流水线' }}</h3><div class="admin-next-doc-options"><label v-for="strategy in strategies" :key="strategy.type"><input type="checkbox" :checked="(key==='parent'?parent:child).includes(strategy.type)" @change="toggle(strategy.type,key)" />{{ strategy.label }}</label></div><ol><li v-for="(type,i) in key==='parent'?parent:child" :key="type" class="admin-next-doc-step"><span>{{ strategies.find(s=>s.type===type)?.label || `未知策略 ${type}` }}</span><Button size="small" :disabled="i===0" :aria-label="`${key} ${type} 上移`" @click="move(i,-1,key)">↑</Button><Button size="small" :disabled="i===(key==='parent'?parent:child).length-1" :aria-label="`${key} ${type} 下移`" @click="move(i,1,key)">↓</Button></li></ol></div></div><div class="admin-next-doc-field"><label for="doc-adjust-note">修改说明</label><Input id="doc-adjust-note" v-model:value="note" /></div><div class="admin-next-doc-field"><label for="doc-operator">操作人 ID</label><Input id="doc-operator" v-model:value="operator" inputmode="numeric" autocomplete="off" /></div></fieldset><p v-if="dirty" class="admin-next-doc-muted">流水线已改动，重新确认后才能构建。</p><p v-if="running" role="status">当前任务进行中，暂不可确认或构建。</p><div class="admin-next-doc-toolbar"><Button :disabled="running||mutation.pending.value||state.loading.value" @click="prepare('confirm',$event)">确认策略</Button><Button type="primary" :disabled="!confirmed||dirty||running||mutation.pending.value||state.loading.value" @click="prepare('index',$event)">构建索引</Button></div></template>
<Modal :open="Boolean(action)" :title="action==='confirm'?'确认策略方案':'确认构建索引'" ok-text="确认提交" cancel-text="取消" :get-container="popupContainer" :ok-button-props="{disabled:mutation.pending.value,loading:mutation.pending.value}" :cancel-button-props="{disabled:mutation.pending.value}" :closable="!mutation.pending.value" :keyboard="!mutation.pending.value" :mask-closable="!mutation.pending.value" centered @ok="submit" @cancel="action=''" @after-close="trigger?.isConnected&&trigger.focus()"><p>{{ document.documentName }}</p><p class="admin-next-doc-id">文档 {{ document.documentId }} · 方案 {{ state.data.value?.plan?.planId }}</p><p v-if="action==='index'">将为此文档创建索引构建任务。</p><p v-else>确认当前父块、子块流水线及其顺序。</p><Alert v-if="mutation.error.value" type="error" :message="mutation.error.value" show-icon /></Modal></section></template>
